def seed_roles_and_migrate_profiles(apps, schema_editor):
    StaffRole = apps.get_model('kahawa', 'StaffRole')
    StaffProfile = apps.get_model('kahawa', 'StaffProfile')

    roles_by_slug = {}
    for i, (slug, (name, description, perms)) in enumerate(ROLE_PRESETS.items()):
        role, _ = StaffRole.objects.update_or_create(
            slug=slug,
            defaults={
                'name': name,
                'description': description,
                'default_permissions': list(perms),
                'is_system': True,
                'sort_order': i,
            },
        )
        roles_by_slug[slug] = role

    for profile in StaffProfile.objects.all():
        old_role = getattr(profile, 'role', None) or 'STAFF'
        slug = 'admin' if old_role == 'ADMIN' else 'barista'
        role = roles_by_slug[slug]
        profile.permissions = list(role.default_permissions)
        profile.save(update_fields=['permissions'])
        profile.roles.set([role])


